M.options = {
  ["initial_cols"] = { applies = "new", default = "80", doc = "Together with initial_rows, configures the window size (window width) for newly created windows. Specifies the width of a new window, expressed in character cells.", t = "int", url = "https://wezterm.org/config/lua/config/initial_cols.html" },
  ["initial_rows"] = { applies = "new", default = "24", doc = "Together with initial_cols, configures the window size (window height) for newly created windows. Specifies the height of a new window, expressed in character cells.", t = "int", url = "https://wezterm.org/config/lua/config/initial_rows.html" },
  ["window_padding.left"] = { doc = "Left: field of window_padding. Controls the amount of padding between the window border and the terminal cells.", note = "Overrides the padding the CRT module derives from the screen radius.", t = "dimension", url = "https://wezterm.org/config/lua/config/window_padding.html" },
  ["window_padding.top"] = { doc = "Top: field of window_padding. Controls the amount of padding between the window border and the terminal cells.", note = "Overrides the padding the CRT module derives from the screen radius.", t = "dimension", url = "https://wezterm.org/config/lua/config/window_padding.html" },
  ["window_padding.right"] = { doc = "Right: field of window_padding. Controls the amount of padding between the window border and the terminal cells.", note = "Overrides the padding the CRT module derives from the screen radius.", t = "dimension", url = "https://wezterm.org/config/lua/config/window_padding.html" },
  ["window_padding.bottom"] = { doc = "Bottom: field of window_padding. Controls the amount of padding between the window border and the terminal cells.", note = "Overrides the padding the CRT module derives from the screen radius.", t = "dimension", url = "https://wezterm.org/config/lua/config/window_padding.html" },
  ["window_content_alignment.horizontal"] = { doc = "Horizontal: field of window_content_alignment. Controls the alignment of the terminal cells inside the window.", t = "enum", url = "https://wezterm.org/config/lua/config/window_content_alignment.html", values = { "Left", "Center", "Right" } },
  ["window_content_alignment.vertical"] = { doc = "Vertical: field of window_content_alignment. Controls the alignment of the terminal cells inside the window.", t = "enum", url = "https://wezterm.org/config/lua/config/window_content_alignment.html", values = { "Top", "Center", "Bottom" } },
  ["adjust_window_size_when_changing_font_size"] = { default = "true", doc = "Control whether changing the font size adjusts the dimensions of the window (true) or adjusts the number of terminal rows/columns (false). The default is true. If you use a tiling window manager then you may wish to set this to false. See also IncreaseFontSize, DecreaseFontSize.", nullable = true, t = "bool", url = "https://wezterm.org/config/lua/config/adjust_window_size_when_changing_font_size.html" },
  ["use_resize_increments"] = { default = "false", doc = "When set to true, prefer to snap the window size to a multiple of the terminal cell size. The default is false, which allows sizing the window to an arbitrary size. This option is only respected on X11, Wayland and macOS systems. Note that if you have configured window_padding then the resize increments don't take the padding into account.", t = "bool", url = "https://wezterm.org/config/lua/config/use_resize_increments.html" },
  ["window_close_confirmation"] = { doc = "Whether to display a confirmation prompt when the window is closed by the windowing environment, either because the user closed it with the window decorations, or instructed their window manager to close it. Set this to \"NeverPrompt\" if you don't like confirming closing windows every time. See also skip_close_confirmation_for_processes_named.", t = "enum", url = "https://wezterm.org/config/lua/config/window_close_confirmation.html", values = { "AlwaysPrompt", "NeverPrompt" } },
  ["quit_when_all_windows_are_closed"] = { default = "true", doc = "When set to true, wezterm will terminate when all windows are closed. This is the default behavior. When set to false, wezterm will continue running.", t = "bool", url = "https://wezterm.org/config/lua/config/quit_when_all_windows_are_closed.html" },
  ["win32_system_backdrop"] = { default = "SETTING", doc = "When combined with window_background_opacity, chooses from available window background effects provided by Windows. The possible values for win32_system_backdrop are: \"Auto\" - the system chooses. In practice, this is the same as \"Disable\". This is the default value. \"Disable\" - disable backdrop effects. \"Acrylic\" - enable the Acrylic blur-behind-window effect. Available on Windows 10 and 11. \"Mica\" - enable the Mica effect, available on Windows 11 build 22621 and later. \"Tabbed\" - enable the Tabbed effect, available on Windows 11 build 22621 and later.", t = "enum", url = "https://wezterm.org/config/lua/config/win32_system_backdrop.html", values = { "Auto", "Disable", "Acrylic", "Mica", "Tabbed" } },
  ["win32_acrylic_accent_color"] = { default = "COLOR", doc = "When combined with win32_system_backdrop = \"Acrylic\" on Windows systems earlier than build 22621, this option specifies the accent color used with the Acrylic composition effect. See also win32_system_backdrop.", t = "color", url = "https://wezterm.org/config/lua/config/win32_acrylic_accent_color.html" },
  ["dpi"] = { doc = "Override the detected DPI (dots per inch) for the display. This can be useful if the detected DPI is inaccurate and the text appears either blurry or too small (especially if you are using a 4K display on X11 or Wayland). The default value is system specific:", nullable = true, t = "float", url = "https://wezterm.org/config/lua/config/dpi.html" },
  ["dpi_by_screen"] = { doc = "DPI to assume per screen, keyed by the screen name; overrides the DPI the system reports.", item = { t = "float" }, t = "map" },
  ["window_decorations"] = { default = "\"TITLE | RESIZE\"", doc = "Configures whether the window has a title bar and/or resizable border. The value is a set of flags: window_decorations = \"NONE\" - disables titlebar and border (borderless mode), but causes problems with resizing and minimizing the window, so you probably want to use RESIZE instead of NONE if you just want to remove the title bar. window_decorations = \"TITLE\" - disable the resizable border and enable only the title bar window_decorations = \"RESIZE\" - disable the title bar but enable the resizable border window_decorations = \"TITLE | RESIZE\" - Enable titlebar and border. This is the default.", empty = "NONE", t = "flags", url = "https://wezterm.org/config/lua/config/window_decorations.html", values = { "TITLE", "RESIZE", "MACOS_FORCE_DISABLE_SHADOW", "MACOS_FORCE_ENABLE_SHADOW", "INTEGRATED_BUTTONS", "MACOS_FORCE_SQUARE_CORNERS", "MACOS_USE_BACKGROUND_COLOR_AS_TITLEBAR_COLOR" } },
  ["integrated_title_buttons"] = { default = "BUTTONS", doc = "Configures the ordering and set of window management buttons to show when window_decorations = \"INTEGRATED_BUTTONS|RESIZE\". The value is a table listing the buttons. Each element can have one of the following values: \"Hide\" - the window hide or minimize button \"Maximize\" - the window maximize button \"Close\" - the window close button", item = { t = "enum", values = { "Hide", "Maximize", "Close", "Settings" } }, t = "list", url = "https://wezterm.org/config/lua/config/integrated_title_buttons.html" },
  ["integrated_title_button_alignment"] = { default = "\"Right\"", doc = "Configures the alignment of the set of window management buttons when window_decorations = \"INTEGRATED_BUTTONS|RESIZE\". Possible values are: \"Left\" - the buttons are shown on the left side of the tab bar \"Right\" - the buttons are shown on the right side of the tab bar", t = "enum", url = "https://wezterm.org/config/lua/config/integrated_title_button_alignment.html", values = { "Right", "Left" } },
  ["integrated_title_button_style"] = { default = "STYLE", doc = "Configures the visual style of the tabbar-integrated titlebar button replacements that are shown when window_decorations = \"INTEGRATED_BUTTONS|RESIZE\". Possible styles are: \"Windows\" - draw Windows-style buttons \"Gnome\" - draw Adwaita-style buttons \"MacOsNative\" - on macOS only, move the native macOS buttons into the tab bar.", t = "enum", url = "https://wezterm.org/config/lua/config/integrated_title_button_style.html", values = { "Windows", "Gnome" } },
  ["integrated_title_button_color"] = { default = "\"Auto\"", doc = "Configures the color of the set of window management buttons when window_decorations = \"INTEGRATED_BUTTONS|RESIZE\". Possible values are: config.integrated_title_button_color = \"Auto\" - automatically compute the color config.integrated_title_button_color = \"red\" - Use a custom color", extra = { "auto" }, t = "color", url = "https://wezterm.org/config/lua/config/integrated_title_button_color.html" },
  ["window_frame.inactive_titlebar_bg"] = { doc = "Inactive titlebar bg: field of window_frame. This setting is applicable primarily on Wayland systems when client side decorations are in use.", t = "color", url = "https://wezterm.org/config/lua/config/window_frame.html" },
  ["window_frame.active_titlebar_bg"] = { doc = "Active titlebar bg: field of window_frame. This setting is applicable primarily on Wayland systems when client side decorations are in use.", t = "color", url = "https://wezterm.org/config/lua/config/window_frame.html" },
  ["window_frame.inactive_titlebar_fg"] = { doc = "Inactive titlebar fg: field of window_frame. This setting is applicable primarily on Wayland systems when client side decorations are in use.", t = "color", url = "https://wezterm.org/config/lua/config/window_frame.html" },
  ["window_frame.active_titlebar_fg"] = { doc = "Active titlebar fg: field of window_frame. This setting is applicable primarily on Wayland systems when client side decorations are in use.", t = "color", url = "https://wezterm.org/config/lua/config/window_frame.html" },
