  ["window_frame.border_right_width"] = { doc = "Border right width: field of window_frame. This setting is applicable primarily on Wayland systems when client side decorations are in use.", t = "dimension", url = "https://wezterm.org/config/lua/config/window_frame.html" },
  ["window_frame.border_top_height"] = { doc = "Border top height: field of window_frame. This setting is applicable primarily on Wayland systems when client side decorations are in use.", t = "dimension", url = "https://wezterm.org/config/lua/config/window_frame.html" },
  ["window_frame.border_bottom_height"] = { doc = "Border bottom height: field of window_frame. This setting is applicable primarily on Wayland systems when client side decorations are in use.", t = "dimension", url = "https://wezterm.org/config/lua/config/window_frame.html" },
  ["window_frame.border_left_color"] = { doc = "Border left color: field of window_frame. This setting is applicable primarily on Wayland systems when client side decorations are in use.", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/window_frame.html" },
  ["window_frame.border_right_color"] = { doc = "Border right color: field of window_frame. This setting is applicable primarily on Wayland systems when client side decorations are in use.", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/window_frame.html" },
  ["window_frame.border_top_color"] = { doc = "Border top color: field of window_frame. This setting is applicable primarily on Wayland systems when client side decorations are in use.", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/window_frame.html" },
  ["window_frame.border_bottom_color"] = { doc = "Border bottom color: field of window_frame. This setting is applicable primarily on Wayland systems when client side decorations are in use.", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/window_frame.html" },
  ["enable_tab_bar"] = { default = "true", doc = "Controls whether the tab bar is enabled. Set to false to disable it. See also hide_tab_bar_if_only_one_tab", t = "bool", url = "https://wezterm.org/config/lua/config/enable_tab_bar.html" },
  ["use_fancy_tab_bar"] = { default = "true", doc = "When set to true (the default), the tab bar is rendered in a native style with proportional fonts. When set to false, the tab bar is rendered using a retro aesthetic using the main terminal font.", t = "bool", url = "https://wezterm.org/config/lua/config/use_fancy_tab_bar.html" },
  ["tab_bar_at_bottom"] = { default = "false", doc = "When tab_bar_at_bottom = true, the tab bar will be rendered at the bottom of the window rather than the top of the window. The default is false.", t = "bool", url = "https://wezterm.org/config/lua/config/tab_bar_at_bottom.html" },
  ["hide_tab_bar_if_only_one_tab"] = { default = "false", doc = "If set to true, when there is only a single tab, the tab bar is hidden from the display. If a second tab is created, the tab will be shown. See also enable_tab_bar", t = "bool", url = "https://wezterm.org/config/lua/config/hide_tab_bar_if_only_one_tab.html" },
  ["show_tabs_in_tab_bar"] = { default = "true", doc = "When set to true (the default), the tab bar will display the tabs associated with the current window. When set to false, the tabs will not be drawn into the tab bar. This example turns off the tabs and new-tab button, leaving just the left and right status areas:", t = "bool", url = "https://wezterm.org/config/lua/config/show_tabs_in_tab_bar.html" },
  ["show_tab_index_in_tab_bar"] = { default = "true", doc = "When set to true (the default), tab titles show their tab number (tab index) with a prefix such as 1:. When false, no numeric prefix is shown. The tab_and_split_indices_are_zero_based setting controls whether numbering starts with 0 or 1.", t = "bool", url = "https://wezterm.org/config/lua/config/show_tab_index_in_tab_bar.html" },
  ["show_new_tab_button_in_tab_bar"] = { default = "true", doc = "When set to true (the default), the tab bar will display the new-tab button, which can be left-clicked to create a new tab, or right-clicked to display the Launcher Menu. When set to false, the new-tab button will not be drawn into the tab bar. This example turns off the tabs and new-tab button, leaving just the left and right status areas:", t = "bool", url = "https://wezterm.org/config/lua/config/show_new_tab_button_in_tab_bar.html" },
  ["show_close_tab_button_in_tabs"] = { default = "true", doc = "When set to false, the close-tab button will not be drawn in tabs when the fancy tab bar is in use. Default is true.", t = "bool", url = "https://wezterm.org/config/lua/config/show_close_tab_button_in_tabs.html" },
  ["tab_max_width"] = { doc = "Specifies the maximum width that a tab can have in the tab bar when using retro tab mode. It is ignored when using fancy tab mode. Defaults to 16 glyphs in width.", t = "int", url = "https://wezterm.org/config/lua/config/tab_max_width.html" },
  ["tab_and_split_indices_are_zero_based"] = { default = "false", doc = "If true, show_tab_index_in_tab_bar uses a zero-based index. The default is false and the tab shows a one-based index.", t = "bool", url = "https://wezterm.org/config/lua/config/tab_and_split_indices_are_zero_based.html" },
  ["mouse_wheel_scrolls_tabs"] = { doc = "If true, the vertical mouse wheel will switch between tabs when the mouse cursor is over the tab bar. The default is true. Set to false to disable this behavior.", t = "bool", url = "https://wezterm.org/config/lua/config/mouse_wheel_scrolls_tabs.html" },
  ["switch_to_last_active_tab_when_closing_tab"] = { default = "false", doc = "If set to true, when the active tab is closed, the previously activated tab will be activated. Otherwise, the tab to the left of the active tab will be activated.", t = "bool", url = "https://wezterm.org/config/lua/config/switch_to_last_active_tab_when_closing_tab.html" },
  ["prefer_to_spawn_tabs"] = { default = "false", doc = "If set to true, launching a new instance of wezterm will prefer to spawn a new tab when it is able to connect to your already-running GUI instance. Otherwise, it will spawn a new window. The default value for this option is false.", t = "bool", url = "https://wezterm.org/config/lua/config/prefer_to_spawn_tabs.html" },
  ["tab_bar_style"] = { doc = "new_tab_left, new_tab_right, new_tab_hover_left, new_tab_hover_right have been removed and replaced by the more flexible new_tab and new_tab_hover elements. active_tab_left, active_tab_right, inactive_tab_left, inactive_tab_right, inactive_tab_hover_left, inactive_tab_hover_right have been removed and replaced by the more flexible format-tab-title event. This config option allows styling the elements that appear in the tab bar. This configuration supplements the tab bar color options.", t = "complex", url = "https://wezterm.org/config/lua/config/tab_bar_style.html" },
  ["status_update_interval"] = { default = "1000", doc = "Specifies the number of milliseconds that need to elapse between triggering the update-status and update-right-status hook.", t = "int", url = "https://wezterm.org/config/lua/config/status_update_interval.html" },
  ["font"] = { doc = "Configures the font to use by default. The font setting can specify a set of fallbacks and other options, and is described in more detail in the Fonts section. You will typically use wezterm.font or wezterm.font_with_fallback to specify the font.", note = "Overrides the CRT profile font (Settings > Font).", t = "font", url = "https://wezterm.org/config/lua/config/font.html" },
  ["font_size"] = { default = "12.0", doc = "Specifies the size of the font, measured in points. You may use fractional point sizes, such as 13.3, to fine tune the size. The default font size is 12.0 points. In earlier versions prior to 20210314-114017-04b7cedd it was 10.0.", note = "Overrides the size the CRT module picks for the font.", t = "float", url = "https://wezterm.org/config/lua/config/font_size.html" },
  ["line_height"] = { default = "1.0", doc = "Scales the computed line height to adjust the spacing between successive rows of text. The default line height is controlled by the font_size configuration option. If you feel that your chosen font feels too vertically cramped then you can set line_height = 1.2 to increase the vertical spacing by 20%. Conversely, setting line_height = 0.9 will decrease the vertical spacing by 10%. See also: cell_width", note = "Overrides the CRT profile line spacing.", t = "float", url = "https://wezterm.org/config/lua/config/line_height.html" },
  ["cell_width"] = { default = "1.0", doc = "Scales the computed cell width to adjust the spacing between successive cells of text. If possible, you should prefer to specify the stretch parameter when selecting a font using wezterm.font or wezterm.font_with_fallback as that will generally look better and have fewer undesirable side effects. If your preferred font doesn't have variations with different stretches, or if the font spacing still doesn't look right to you, then cell_width gives you a simple way to influence the spacing.", t = "float", url = "https://wezterm.org/config/lua/config/cell_width.html" },
  ["font_dirs"] = { append = true, doc = "By default, wezterm will use an appropriate system-specific method for locating the fonts that you specify using the options below. In addition, if you configure the font_dirs option, wezterm will load fonts from that set of directories: wezterm will scan the font_dirs to build a database of available fonts. When resolving a font, wezterm will first use the configured font_locator which is typically the system specific font resolver. If the system doesn't resolve the requested font, the fonts from font_dirs are searched for a match. If you want to only find fonts from your font_dirs, perhaps because you have a self-contained wezterm config that you carry around with you between multiple systems and don't want to install those fonts on every system that you use, then you can set:", item = { t = "path" }, t = "list", url = "https://wezterm.org/config/lua/config/font_dirs.html" },
  ["font_rules"] = { doc = "When textual output in the terminal is styled with bold, italic or other attributes, wezterm uses font_rules to decide how to render that text. By default, unstyled text will use the font specified by the font configuration, and wezterm will use that as a base, and then automatically generate appropriate font_rules that use heavier weight fonts for bold text, lighter weight fonts for dim text and italic fonts for italic text. Most users won't need to specify any explicit value for font_rules, as the defaults should be sufficient.", t = "complex", url = "https://wezterm.org/config/lua/config/font_rules.html" },
  ["font_locator"] = { doc = "specifies the method by which system fonts are located and loaded. You may specify ConfigDirsOnly to disable loading system fonts and use only the fonts found in the directories that you specify in your font_dirs configuration option. Otherwise, it is recommended to omit this setting.", t = "enum", url = "https://wezterm.org/config/lua/config/font_locator.html", values = { "FontConfig", "Gdi", "CoreText", "ConfigDirsOnly" } },
  ["font_rasterizer"] = { doc = "Specifies the method by which fonts are rendered on screen. The only available implementation is FreeType.", t = "enum", url = "https://wezterm.org/config/lua/config/font_rasterizer.html", values = { "FreeType", "Harfbuzz" } },
  ["font_colr_rasterizer"] = { doc = "Rasterizer used for color (COLR) emoji fonts.", t = "enum", values = { "FreeType", "Harfbuzz" } },
  ["font_shaper"] = { doc = "specifies the method by which text is mapped to glyphs in the available fonts. The shaper is responsible for handling kerning, ligatures and emoji composition. The default is Harfbuzz and we have very preliminary support for Allsorts. It is strongly recommended that you use the default Harfbuzz shaper. The incomplete Allsorts shaper was removed.", t = "enum", url = "https://wezterm.org/config/lua/config/font_shaper.html", values = { "Allsorts", "Harfbuzz" } },
  ["harfbuzz_features"] = { doc = "When font_shaper = \"Harfbuzz\", this setting affects how font shaping takes place. See Font Shaping for more information and examples.", item = { t = "string" }, t = "list", url = "https://wezterm.org/config/lua/config/harfbuzz_features.html" },
  ["freetype_load_target"] = { default = "\"Normal\"", doc = "Configures the hinting and (potentially) the rendering mode used with the freetype rasterizer. The following values are possible: \"Normal\" - This corresponds to the default hinting algorithm, optimized for standard gray-level rendering. This is the default setting. \"Light\" - A lighter hinting algorithm for non-monochrome modes. Many generated glyphs are more fuzzy but better resemble its original shape. A bit like rendering on Mac OS X. \"Mono\" - Strong hinting algorithm that should only be used for monochrome output. The result is probably unpleasant if the glyph is rendered in non-monochrome modes. \"HorizontalLcd\" - A subpixel-rendering variant of Normal optimized for horizontally decimated LCD displays. See also freetype_render_target and freetype_load_flags for more advanced flags that can be primarily used to influence font hinting.", note = "The CRT module uses Mono for pixel fonts.", t = "enum", url = "https://wezterm.org/config/lua/config/freetype_load_target.html", values = { "Normal", "Light", "Mono", "HorizontalLcd", "VerticalLcd" } },
  ["freetype_render_target"] = { default = "\"Normal\"", doc = "Configures the rendering mode used with the freetype rasterizer. The default is to use the value of freetype_load_target. You may wish to override that value if you want very fine control over how freetype hints and then renders glyphs.", note = "The CRT module uses Mono for pixel fonts.", nullable = true, t = "enum", url = "https://wezterm.org/config/lua/config/freetype_render_target.html", values = { "Normal", "Light", "Mono", "HorizontalLcd", "VerticalLcd" } },
  ["freetype_load_flags"] = { default = "\"DEFAULT\"", doc = "An advanced option to fine tune the freetype rasterizer. This is a bitfield, so you can combine one or more of these options together, separated by the | character, although not many of the available options necessarily make sense to be combined. Available flags are: DEFAULT - This is the default! NO_HINTING - Disable hinting. The freetype documentation says that this generally generates ‘blurrier’ bitmap glyph when the glyph is rendered in any of the anti-aliased modes, but that was written for rasterizing direct to bitmaps. In the context of wezterm where we are rasterizing to a texture that is then sampled and applied to a framebuffer through vertices on the GPU, the hinting process can be counter-productive and result in unexpected visual artifacts. NO_BITMAP - don't load any pre-rendered bitmap strikes FORCE_AUTOHINT - Use the freetype auto-hinter rather than the font's native hinter. MONOCHROME - instructs renderer to use 1-bit monochrome rendering. This option doesn't impact the hinter. NO_AUTOHINT - don't use the freetype auto-hinter", empty = "DEFAULT", nullable = true, t = "flags", url = "https://wezterm.org/config/lua/config/freetype_load_flags.html", values = { "NO_HINTING", "NO_BITMAP", "FORCE_AUTOHINT", "MONOCHROME", "NO_AUTOHINT", "NO_SVG", "SVG_ONLY" } },
  ["freetype_interpreter_version"] = { doc = "Selects the freetype interpret version to use. Possible values are 35, 38 and 40 which have different characteristics with respective to subpixel hinting. See", nullable = true, t = "int", url = "https://wezterm.org/config/lua/config/freetype_interpreter_version.html" },
  ["freetype_pcf_long_family_names"] = { default = "false", doc = "This option provides control over the no-long-family-names FreeType PCF font driver property. The default is for this configuration to be false which sets the PCF driver to use the un-decorated font name. This corresponds to the default mode of operation of the freetype library. Some Linux distributions build the freetype library in a way that causes the PCF driver to report font names differently; instead of reporting just Terminus it will prefix the font name with the foundry (xos4 in the case of Terminus) and potentially append Wide to the name if the font has wide glyphs. The purpose of that configuration option is to disambiguate fonts, as there are a number of fonts from different foundries that all have the name Fixed, and being presented with multiple items with the same Fixed label is a very ambiguous user experience.", t = "bool", url = "https://wezterm.org/config/lua/config/freetype_pcf_long_family_names.html" },
  ["display_pixel_geometry"] = { default = "\"RGB\"", doc = "Configures whether subpixel anti-aliasing should produce either \"RGB\" or \"BGR\" ordered output. If your display has a BGR pixel geometry then you will want to set this to \"BGR\" for the best results when using subpixel antialiasing. The default value is \"RGB\".", t = "enum", url = "https://wezterm.org/config/lua/config/display_pixel_geometry.html", values = { "RGB", "BGR" } },
  ["allow_square_glyphs_to_overflow_width"] = { default = "\"Never\"", doc = "Configures how square symbol glyph's cell is rendered: \"WhenFollowedBySpace\" - (this is the default) deliberately overflow the cell width when the next cell is a space. \"Always\" - overflow the cell regardless of the next cell being a space. \"Never\" - strictly respect the cell width. This setting now applies to any glyph with an aspect ratio larger than 0.9, which covers more symbol glyphs than in earlier releases.", t = "enum", url = "https://wezterm.org/config/lua/config/allow_square_glyphs_to_overflow_width.html", values = { "Never", "Always", "WhenFollowedBySpace" } },
  ["custom_block_glyphs"] = { doc = "When set to true (the default), WezTerm will compute its own idea of what the glyphs in the following unicode ranges should be, instead of using glyphs resolved from a font. Ideally this option wouldn't exist, but it is present to work around a hinting issue in freetype. You can set this to false to use the block characters provided by your font selection.", t = "bool", url = "https://wezterm.org/config/lua/config/custom_block_glyphs.html" },
  ["anti_alias_custom_block_glyphs"] = { doc = "Control whether custom_block_glyphs are rendered using anti-aliasing or not. Anti-aliasing makes lines look smoother but may not look so nice at smaller font sizes.", t = "bool", url = "https://wezterm.org/config/lua/config/anti_alias_custom_block_glyphs.html" },
  ["warn_about_missing_glyphs"] = { doc = "When set to true, if a glyph cannot be found for a given codepoint, then the configuration error window will be shown with a pointer to the font configuration docs. You can set warn_about_missing_glyphs = false to prevent the configuration error window from being displayed. The default is warn_about_missing_glyphs = true.", t = "bool", url = "https://wezterm.org/config/lua/config/warn_about_missing_glyphs.html" },
  ["sort_fallback_fonts_by_coverage"] = { doc = "Order fallback fonts by how many of the needed glyphs they contain.", t = "bool" },
  ["search_font_dirs_for_fallback"] = { doc = "Search font_dirs as well when looking for fallback fonts.", t = "bool" },
  ["use_cap_height_to_scale_fallback_fonts"] = { default = "false", doc = "When set to true, use the cap-height font metrics of the base and the current font to adjust the size of secondary fonts (such as bold or italic faces) to visually match the size of the base font. The default is false.", t = "bool", url = "https://wezterm.org/config/lua/config/use_cap_height_to_scale_fallback_fonts.html" },
  ["ignore_svg_fonts"] = { doc = "Skip fonts that contain SVG glyphs.", t = "bool" },
  ["underline_thickness"] = { doc = "If specified, overrides the base thickness of underlines. The underline thickness is also used for rendering split pane dividers and a number of other lines in custom glyphs. The default is to use the underline thickness metric specified by the designer of the primary font. This config option accepts different units that have slightly different interpretations:", nullable = true, t = "dimension", url = "https://wezterm.org/config/lua/config/underline_thickness.html" },
  ["underline_position"] = { doc = "If specified, overrides the position of underlines. The default is to use the underline position metric specified by the designer of the primary font. This config option accepts different units that have slightly different interpretations:", nullable = true, t = "dimension", url = "https://wezterm.org/config/lua/config/underline_position.html" },
  ["strikethrough_position"] = { doc = "If specified, overrides the position of strikethrough lines. The default is derived from the underline position metric specified by the designer of the primary font. This config option accepts different units that have slightly different interpretations:", nullable = true, t = "dimension", url = "https://wezterm.org/config/lua/config/strikethrough_position.html" },
  ["experimental_pixel_positioning"] = { doc = "Position glyphs at fractional pixel positions (experimental).", t = "bool" },
  ["use_box_model_render"] = { doc = "Render with the box model (experimental layout engine).", t = "bool" },
  ["color_scheme"] = { doc = "Use a named color scheme rather than the palette specified by the colors setting.", nullable = true, t = "string" },
  ["color_scheme_dirs"] = { append = true, doc = "Directories searched for color scheme files (TOML), in addition to the built-in schemes.", item = { t = "path" }, t = "list" },
  ["color_schemes"] = { doc = "Specifies various named color schemes in your configuration file. Described in more detail in Colors & Appearance", t = "complex", url = "https://wezterm.org/config/lua/config/color_schemes.html" },
  ["colors.foreground"] = { doc = "The text color to use when the attributes are reset to default", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.background"] = { doc = "The background color to use when the attributes are reset to default", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.cursor_fg"] = { doc = "The color of the cursor", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.cursor_bg"] = { doc = "Cursor bg: field of colors. Specifies the color palette.", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.cursor_border"] = { doc = "Cursor border: field of colors. Specifies the color palette.", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.selection_fg"] = { doc = "The color of selected text", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.selection_bg"] = { doc = "Selection bg: field of colors. Specifies the color palette.", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.ansi"] = { doc = "A list of 8 colors corresponding to the basic ANSI palette", nullable = true, t = "complex", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.brights"] = { doc = "A list of 8 colors corresponding to bright versions of the ANSI palette", nullable = true, t = "complex", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.indexed"] = { doc = "A map for setting arbitrary colors ranging from 16 to 256 in the color palette", t = "complex", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.scrollbar_thumb"] = { doc = "The color of the \"thumb\" of the scrollbar; the segment that represents the current viewable area", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.split"] = { doc = "The color of the split line between panes", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.visual_bell"] = { doc = "The color of the visual bell. If unspecified, the foreground color is used instead.", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.compose_cursor"] = { doc = "The color to use for the cursor when a dead key or leader state is active", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.compose_fg"] = { doc = "The foreground color for composition/IME preview text (e.g., dictation)", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.compose_bg"] = { doc = "The background color for composition/IME preview text (e.g., dictation)", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.copy_mode_active_highlight_fg"] = { doc = "Copy mode active highlight fg: field of colors. Specifies the color palette.", nullable = true, t = "colorspec", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.copy_mode_active_highlight_bg"] = { doc = "Copy mode active highlight bg: field of colors. Specifies the color palette.", nullable = true, t = "colorspec", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.copy_mode_inactive_highlight_fg"] = { doc = "Copy mode inactive highlight fg: field of colors. Specifies the color palette.", nullable = true, t = "colorspec", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.copy_mode_inactive_highlight_bg"] = { doc = "Copy mode inactive highlight bg: field of colors. Specifies the color palette.", nullable = true, t = "colorspec", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.quick_select_label_fg"] = { doc = "Quick select label fg: field of colors. Specifies the color palette.", nullable = true, t = "colorspec", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.quick_select_label_bg"] = { doc = "Quick select label bg: field of colors. Specifies the color palette.", nullable = true, t = "colorspec", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.quick_select_match_fg"] = { doc = "Quick select match fg: field of colors. Specifies the color palette.", nullable = true, t = "colorspec", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.quick_select_match_bg"] = { doc = "Quick select match bg: field of colors. Specifies the color palette.", nullable = true, t = "colorspec", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.input_selector_label_fg"] = { doc = "Input selector label fg: field of colors. Specifies the color palette.", nullable = true, t = "colorspec", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.input_selector_label_bg"] = { doc = "Input selector label bg: field of colors. Specifies the color palette.", nullable = true, t = "colorspec", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.launcher_label_fg"] = { doc = "Launcher label fg: field of colors. Specifies the color palette.", nullable = true, t = "colorspec", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.launcher_label_bg"] = { doc = "Launcher label bg: field of colors. Specifies the color palette.", nullable = true, t = "colorspec", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["bold_brightens_ansi_colors"] = { default = "true", doc = "When true (the default), PaletteIndex 0-7 are shifted to bright when the font intensity is bold. This brightening effect doesn't occur when the text is set to the default foreground color! This defaults to true for better compatibility with a wide range of mature software; for instance, a lot of software assumes that Black+Bold renders as a Dark Grey which is legible on a Black background, but if this option is set to false, it would render as Black on Black.", t = "enum", url = "https://wezterm.org/config/lua/config/bold_brightens_ansi_colors.html", values = { "No", "BrightAndBold", "BrightOnly" } },
  ["text_min_contrast_ratio"] = { default = "nil", doc = "An optional floating point value that defaults to nil (not being set). When set, it defines the minimum contrast ratio between the foreground and background color of a textual cell, when the cell has differing foreground and background colors. If the color attributes of a cell fall below the minimum contrast ratio, then the foreground color will have its luminance (perceived brightness) adjusted to try to boost the contrast ratio to meet the specified minimum.", nullable = true, t = "float", url = "https://wezterm.org/config/lua/config/text_min_contrast_ratio.html" },
  ["foreground_text_hsb.hue"] = { doc = "Hue: field of foreground_text_hsb. Configures a Hue, Saturation, Brightness transformation that is applied to monochrome glyphs.", t = "float", url = "https://wezterm.org/config/lua/config/foreground_text_hsb.html" },
  ["foreground_text_hsb.saturation"] = { doc = "Saturation: field of foreground_text_hsb. Configures a Hue, Saturation, Brightness transformation that is applied to monochrome glyphs.", t = "float", url = "https://wezterm.org/config/lua/config/foreground_text_hsb.html" },
  ["foreground_text_hsb.brightness"] = { doc = "Brightness: field of foreground_text_hsb. Configures a Hue, Saturation, Brightness transformation that is applied to monochrome glyphs.", t = "float", url = "https://wezterm.org/config/lua/config/foreground_text_hsb.html" },
  ["colors.tab_bar.background"] = { doc = "The background color for the tab bar", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.active_tab.intensity"] = { doc = "Specifies the intensity attribute for the tab title text", t = "enum", url = "https://wezterm.org/config/lua/config/colors.html", values = { "Normal", "Bold", "Half" } },
  ["colors.tab_bar.active_tab.underline"] = { doc = "Specifies the underline attribute for the tab title text", t = "enum", url = "https://wezterm.org/config/lua/config/colors.html", values = { "None", "Single", "Double", "Curly", "Dotted", "Dashed" } },
  ["colors.tab_bar.active_tab.italic"] = { doc = "Specifies the italic attribute for the tab title text", t = "bool", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.active_tab.strikethrough"] = { doc = "Specifies the strikethrough attribute for the tab title text", t = "bool", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.active_tab.bg_color"] = { doc = "The background color for the tab", t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.active_tab.fg_color"] = { doc = "The forgeground/text color for the tab", t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.inactive_tab.intensity"] = { doc = "Specifies the intensity attribute for the tab title text", t = "enum", url = "https://wezterm.org/config/lua/config/colors.html", values = { "Normal", "Bold", "Half" } },
  ["colors.tab_bar.inactive_tab.underline"] = { doc = "Specifies the underline attribute for the tab title text", t = "enum", url = "https://wezterm.org/config/lua/config/colors.html", values = { "None", "Single", "Double", "Curly", "Dotted", "Dashed" } },
  ["colors.tab_bar.inactive_tab.italic"] = { doc = "Specifies the italic attribute for the tab title text", t = "bool", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.inactive_tab.strikethrough"] = { doc = "Specifies the strikethrough attribute for the tab title text", t = "bool", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.inactive_tab.bg_color"] = { doc = "The background color for the tab", t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.inactive_tab.fg_color"] = { doc = "The forgeground/text color for the tab", t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.inactive_tab_hover.intensity"] = { doc = "Specifies the intensity attribute for the tab title text", t = "enum", url = "https://wezterm.org/config/lua/config/colors.html", values = { "Normal", "Bold", "Half" } },
  ["colors.tab_bar.inactive_tab_hover.underline"] = { doc = "Specifies the underline attribute for the tab title text", t = "enum", url = "https://wezterm.org/config/lua/config/colors.html", values = { "None", "Single", "Double", "Curly", "Dotted", "Dashed" } },
  ["colors.tab_bar.inactive_tab_hover.italic"] = { doc = "Specifies the italic attribute for the tab title text", t = "bool", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.inactive_tab_hover.strikethrough"] = { doc = "Specifies the strikethrough attribute for the tab title text", t = "bool", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.inactive_tab_hover.bg_color"] = { doc = "The background color for the tab", t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.inactive_tab_hover.fg_color"] = { doc = "The forgeground/text color for the tab", t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.new_tab.intensity"] = { doc = "Specifies the intensity attribute for the tab title text", t = "enum", url = "https://wezterm.org/config/lua/config/colors.html", values = { "Normal", "Bold", "Half" } },
  ["colors.tab_bar.new_tab.underline"] = { doc = "Specifies the underline attribute for the tab title text", t = "enum", url = "https://wezterm.org/config/lua/config/colors.html", values = { "None", "Single", "Double", "Curly", "Dotted", "Dashed" } },
  ["colors.tab_bar.new_tab.italic"] = { doc = "Specifies the italic attribute for the tab title text", t = "bool", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.new_tab.strikethrough"] = { doc = "Specifies the strikethrough attribute for the tab title text", t = "bool", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.new_tab.bg_color"] = { doc = "The background color for the tab", t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.new_tab.fg_color"] = { doc = "The forgeground/text color for the tab", t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.new_tab_hover.intensity"] = { doc = "Specifies the intensity attribute for the tab title text", t = "enum", url = "https://wezterm.org/config/lua/config/colors.html", values = { "Normal", "Bold", "Half" } },
  ["colors.tab_bar.new_tab_hover.underline"] = { doc = "Specifies the underline attribute for the tab title text", t = "enum", url = "https://wezterm.org/config/lua/config/colors.html", values = { "None", "Single", "Double", "Curly", "Dotted", "Dashed" } },
  ["colors.tab_bar.new_tab_hover.italic"] = { doc = "Specifies the italic attribute for the tab title text", t = "bool", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.new_tab_hover.strikethrough"] = { doc = "Specifies the strikethrough attribute for the tab title text", t = "bool", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.new_tab_hover.bg_color"] = { doc = "The background color for the tab", t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.new_tab_hover.fg_color"] = { doc = "The forgeground/text color for the tab", t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.inactive_tab_edge"] = { doc = "Inactive tab edge: field of colors.tab_bar. Specifies the color palette.", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["colors.tab_bar.inactive_tab_edge_hover"] = { doc = "Inactive tab edge hover: field of colors.tab_bar. Specifies the color palette.", nullable = true, t = "color", url = "https://wezterm.org/config/lua/config/colors.html" },
  ["window_background_opacity"] = { default = "1.0", doc = "Specifies the alpha channel value for the window background. If your Operating System provides compositing support, the window background is rendered translucent (some refer to this as transparent rather than translucent), causing the windows and desktop behind it to show through. The value is a floating point number in the range 0.0 (completely translucent/transparent) through to 1.0 (completely opaque), which is the default. The opacity also applies to the window_background_image and window_background_gradient layers.", t = "float", url = "https://wezterm.org/config/lua/config/window_background_opacity.html" },
  ["text_background_opacity"] = { doc = "Opacity of the background color of text cells (0..1), separate from window_background_opacity.", t = "float" },
  ["window_background_image"] = { doc = "You can attach an image to the background of the wezterm window: If the path is a relative path then it will be expanded relative to the directory containing your wezterm.lua config file. PNG, JPEG, GIF, BMP, ICO, TIFF, PNM, DDS, TGA and farbfeld files can be loaded. Animated GIF and PNG files will animate while the window has focus.", nullable = true, t = "path", url = "https://wezterm.org/config/lua/config/window_background_image.html" },
  ["window_background_image_hsb.hue"] = { doc = "Hue: field of window_background_image_hsb. Configures a Hue, Saturation, Brightness transformation that is applied to the window_background_image.", t = "float", url = "https://wezterm.org/config/lua/config/window_background_image_hsb.html" },
  ["window_background_image_hsb.saturation"] = { doc = "Saturation: field of window_background_image_hsb. Configures a Hue, Saturation, Brightness transformation that is applied to the window_background_image.", t = "float", url = "https://wezterm.org/config/lua/config/window_background_image_hsb.html" },
  ["window_background_image_hsb.brightness"] = { doc = "Brightness: field of window_background_image_hsb. Configures a Hue, Saturation, Brightness transformation that is applied to the window_background_image.", t = "float", url = "https://wezterm.org/config/lua/config/window_background_image_hsb.html" },
  ["window_background_gradient"] = { doc = "Dynamically generates a window_background_image from the provided gradient specification. When window_background_gradient is configured, the value for window_background_image is ignored. Linear gradients with vertical or horizontal orientation are supported: Gradients are implemented using the colorgrad crate. Take a look at for some usage examples and additional information about gradients.", nullable = true, t = "complex", url = "https://wezterm.org/config/lua/config/window_background_gradient.html" },
  ["background"] = { doc = "The background config option allows you to compose a number of layers to produce the background content in the terminal. Layers can be image files, gradients or solid blocks of color. Layers composite over each other based on their alpha channel. Images in layers can be made to fill the viewport or to tile, and also to scroll with optional parallax as the viewport is scrolled. This video demonstrates the use of multiple layers to produce a rich video game style parallax background; the configuration used for this is shown as an example at the bottom of this page:", t = "complex", url = "https://wezterm.org/config/lua/config/background.html" },
  ["default_cursor_style"] = { default = "\"SteadyBlock\"", doc = "Specifies the default cursor style. Various escape sequences can override the default style in different situations (eg: an editor can change it depending on the mode), but this value controls how the cursor appears when it is reset to default. The default is SteadyBlock. Acceptable values are SteadyBlock, BlinkingBlock, SteadyUnderline, BlinkingUnderline, SteadyBar, and BlinkingBar. Using a blinking style puts more load on the graphics subsystem. animation_fps can be used to tune the frame rate used for easing in the blink animation.", note = "Overrides the cursor style of the CRT profile.", t = "enum", url = "https://wezterm.org/config/lua/config/default_cursor_style.html", values = { "BlinkingBlock", "SteadyBlock", "BlinkingUnderline", "SteadyUnderline", "BlinkingBar", "SteadyBar" } },
  ["cursor_blink_rate"] = { doc = "Specifies how often a blinking cursor transitions between visible and invisible, expressed in milliseconds. Setting this to 0 disables blinking. Note that this value is approximate due to the way that the system event loop schedulers manage timers; non-zero values will be at least the interval specified with some degree of slop. It is recommended to avoid blinking cursors when on battery power, as it is relatively costly to keep re-rendering for the blink!", t = "int", url = "https://wezterm.org/config/lua/config/cursor_blink_rate.html" },
  ["cursor_blink_ease_in"] = { default = "\"Linear\"", doc = "Specifies the easing function to use when computing the color for the text cursor when it is set to a blinking style. See visual_bell for more information about easing functions.", t = "enum", url = "https://wezterm.org/config/lua/config/cursor_blink_ease_in.html", values = { "Linear", "Ease", "EaseIn", "EaseInOut", "EaseOut", "Constant" } },
  ["cursor_blink_ease_out"] = { default = "\"Linear\"", doc = "Specifies the easing function to use when computing the color for the text cursor when it is set to a blinking style. See visual_bell for more information about easing functions.", t = "enum", url = "https://wezterm.org/config/lua/config/cursor_blink_ease_out.html", values = { "Linear", "Ease", "EaseIn", "EaseInOut", "EaseOut", "Constant" } },
  ["cursor_thickness"] = { doc = "If specified, overrides the base thickness of the lines used to render the textual cursor glyph. The default is to use the underline_thickness. This config option accepts different units that have slightly different interpretations:", nullable = true, t = "dimension", url = "https://wezterm.org/config/lua/config/cursor_thickness.html" },
  ["force_reverse_video_cursor"] = { default = "false", doc = "When force_reverse_video_cursor = true, override the cursor_fg, cursor_bg, cursor_border settings from the color scheme and force the cursor to use reverse video colors based on the foreground and background colors. When force_reverse_video_cursor = false (the default), cursor_fg, cursor_bg and cursor_border color scheme settings are applied as normal. If escape sequences are used to change the cursor color, they will take precedence over force_reverse_video_cursor. In earlier releases, setting force_reverse_video_cursor = true always ignored the configured cursor color.", t = "bool", url = "https://wezterm.org/config/lua/config/force_reverse_video_cursor.html" },
  ["reverse_video_cursor_min_contrast"] = { default = "2.5", doc = "The minimum contrast ratio required to use the reverse video cursor. When the contrast ratio between the reverse video cursor foreground and background is below this threshold then the default cursor foreground and background will be used instead.", t = "float", url = "https://wezterm.org/config/lua/config/reverse_video_cursor_min_contrast.html" },
  ["animation_fps"] = { default = "10", doc = "This setting controls the maximum frame rate used when rendering easing effects for blinking cursors, blinking text and visual bell. Setting it larger will result in smoother easing effects but will increase GPU utilization. If you are running with a CPU renderer (eg: you have front_end = \"Software\", or your system doesn't have a GPU), then setting animation_fps = 1 is recommended, as doing so will disable easing effects and use transitions:", t = "int", url = "https://wezterm.org/config/lua/config/animation_fps.html" },
  ["text_blink_rate"] = { doc = "Specifies how often blinking text (normal speed) transitions between visible and invisible, expressed in milliseconds. Setting this to 0 disables slow text blinking. Note that this value is approximate due to the way that the system event loop schedulers manage timers; non-zero values will be at least the interval specified with some degree of slop. Blinking is no longer a binary blink, but interpolates between invisible and visible text using an easing function. See text_blink_ease_in and text_blink_ease_out for more information.", t = "int", url = "https://wezterm.org/config/lua/config/text_blink_rate.html" },
  ["text_blink_ease_in"] = { default = "\"Linear\"", doc = "Specifies the easing function to use when computing the color for text that has the blinking attribute in the fading-in phase--when the text is fading from the background color to the foreground color. See visual_bell for more information about easing functions. See cursor_blink_rate to control the rate at which the cursor blinks.", t = "enum", url = "https://wezterm.org/config/lua/config/text_blink_ease_in.html", values = { "Linear", "Ease", "EaseIn", "EaseInOut", "EaseOut", "Constant" } },
  ["text_blink_ease_out"] = { default = "\"Linear\"", doc = "Specifies the easing function to use when computing the color for text that has the blinking attribute in the fading-out phase--when the text is fading from the foreground color to the background color. See visual_bell for more information about easing functions.", t = "enum", url = "https://wezterm.org/config/lua/config/text_blink_ease_out.html", values = { "Linear", "Ease", "EaseIn", "EaseInOut", "EaseOut", "Constant" } },
  ["text_blink_rate_rapid"] = { doc = "Specifies how often blinking text (rapid speed) transitions between visible and invisible, expressed in milliseconds. Setting this to 0 disables rapid text blinking. Note that this value is approximate due to the way that the system event loop schedulers manage timers; non-zero values will be at least the interval specified with some degree of slop. Blinking is no longer a binary blink, but interpolates between invisible and visible text using an easing function. See text_blink_rapid_ease_in and text_blink_rapid_ease_out for more information.", t = "int", url = "https://wezterm.org/config/lua/config/text_blink_rate_rapid.html" },
  ["text_blink_rapid_ease_in"] = { default = "\"Linear\"", doc = "Specifies the easing function to use when computing the color for text that has the rapid blinking attribute in the fading-in phase--when the text is fading from the background color to the foreground color. See visual_bell for more information about easing functions.", t = "enum", url = "https://wezterm.org/config/lua/config/text_blink_rapid_ease_in.html", values = { "Linear", "Ease", "EaseIn", "EaseInOut", "EaseOut", "Constant" } },
  ["text_blink_rapid_ease_out"] = { default = "\"Linear\"", doc = "Specifies the easing function to use when computing the color for text that has the rapid blinking attribute in the fading-out phase--when the text is fading from the foreground color to the background color. See visual_bell for more information about easing functions.", t = "enum", url = "https://wezterm.org/config/lua/config/text_blink_rapid_ease_out.html", values = { "Linear", "Ease", "EaseIn", "EaseInOut", "EaseOut", "Constant" } },
  ["scrollback_lines"] = { applies = "new", default = "3500", doc = "How many lines of scrollback you want to retain. Learn more about scrollback", t = "int", url = "https://wezterm.org/config/lua/config/scrollback_lines.html" },
  ["enable_scroll_bar"] = { doc = "Enable the scrollbar. This is currently disabled by default. It will occupy the right window padding space. If right padding is set to 0 then it will be increased to a single cell width.", t = "bool", url = "https://wezterm.org/config/lua/config/enable_scroll_bar.html" },
  ["min_scroll_bar_height"] = { default = "\"0.5cell\"", doc = "Controls the minimum size of the scroll bar \"thumb\". The value can be a number to specify the number of pixels, or a string with a unit suffix: \"1px\" - the px suffix indicates pixels, so this represents a 1 pixel value \"1pt\" - the pt suffix indicates points. There are 72 points in 1 inch. The actual size this occupies on screen depends on the dpi of the display device. \"1cell\" - the cell suffix indicates the height of the terminal cell, which in turn depends on the font size, font scaling and dpi. \"1%\" - the % suffix indicates the size of the terminal portion of the display, which is computed based on the number of rows and the size of the cell.", t = "dimension", url = "https://wezterm.org/config/lua/config/min_scroll_bar_height.html" },
  ["scroll_to_bottom_on_input"] = { doc = "When true (the default), the viewport will automatically scroll to the bottom of the scrollback when there is input to the terminal so that you can see what you are typing.", t = "bool", url = "https://wezterm.org/config/lua/config/scroll_to_bottom_on_input.html" },
  ["alternate_buffer_wheel_scroll_speed"] = { default = "3", doc = "Normally the vertical mouse wheel will scroll the terminal viewport so that different sections of the scrollback are visible. When an application activates the Alternate Screen Buffer (this is common for \"full screen\" terminal programs such as pagers and editors), the alternate screen doesn't have a scrollback. In this mode, if the application hasn't enabled mouse reporting, wezterm will generate Arrow Up/Down key events when the vertical mouse wheel is scrolled.", t = "int", url = "https://wezterm.org/config/lua/config/alternate_buffer_wheel_scroll_speed.html" },
  ["keys"] = { doc = "Key bindings: a list of { key, mods, action } entries.", t = "complex" },
  ["key_tables"] = { default = "{}", doc = "See the main Key Tables docs!", t = "complex", url = "https://wezterm.org/config/lua/config/key_tables.html" },
  ["leader"] = { doc = "Leader key: a modal key combination that enables LEADER bindings for a short time.", nullable = true, t = "complex" },
  ["disable_default_key_bindings"] = { doc = "Turn off all of the default key bindings; only the keys you define stay.", t = "bool" },
  ["key_map_preference"] = { default = "\"Mapped\"", doc = "Controls how keys without an explicit phys: or mapped: prefix are treated. If key_map_preference = \"Mapped\" (the default), then mapped: is assumed. If key_map_preference = \"Physical\" then phys: is assumed. Default key assignments also respect key_map_preference.", t = "enum", url = "https://wezterm.org/config/lua/config/key_map_preference.html", values = { "Physical", "Mapped" } },
  ["use_dead_keys"] = { doc = "Dead keys produce diacritics (e.g. ^ then e gives a circumflex e); off makes them regular keys.", t = "bool" },
  ["send_composed_key_when_left_alt_is_pressed"] = { doc = "With left Alt held, send the character the keyboard layout composes instead of Alt+key.", t = "bool" },
  ["send_composed_key_when_right_alt_is_pressed"] = { doc = "With right Alt (AltGr) held, send the character the keyboard layout composes instead of Alt+key.", t = "bool" },
  ["treat_left_ctrlalt_as_altgr"] = { default = "false", doc = "If you are using a layout with an AltGr key, you may experience issues when running inside a VNC session, because VNC emulates the AltGr keypresses by sending plain Ctrl-Alt keys, which won't be understood as AltGr. To fix this behavior you can tell WezTerm to treat left Ctrl-Alt keys as AltGr with the option treat_left_ctrlalt_as_altgr. Note that the key bindings using separate Ctrl and Alt won't be triggered anymore.", t = "bool", url = "https://wezterm.org/config/lua/config/treat_left_ctrlalt_as_altgr.html" },
  ["swap_backspace_and_delete"] = { default = "false", doc = "When set to true, switch the interpretation of the Backspace and Delete keys such that Backspace generates Delete and vice versa.", t = "bool", url = "https://wezterm.org/config/lua/config/swap_backspace_and_delete.html" },
  ["enable_csi_u_key_encoding"] = { default = "false", doc = "When set to true, the keyboard encoding will be changed to use the scheme that is described here. It is not recommended to enable this option as it does change the behavior of some keys in backwards incompatible ways and there isn't a way for applications to detect or request this behavior. The default for this option is false.", t = "bool", url = "https://wezterm.org/config/lua/config/enable_csi_u_key_encoding.html" },
  ["enable_kitty_keyboard"] = { default = "false", doc = "When set to true, wezterm will honor kitty keyboard protocol escape sequences that modify the keyboard encoding.", t = "bool", url = "https://wezterm.org/config/lua/config/enable_kitty_keyboard.html" },
  ["allow_win32_input_mode"] = { doc = "When set to true, wezterm will honor an escape sequence generated by the Windows ConPTY layer to switch the keyboard encoding to a proprietary scheme that has maximum compatibility with win32 console applications. See also Improved Keyboard Handling in ConPTY. The default for allow_win32_input_mode is now true.", t = "bool", url = "https://wezterm.org/config/lua/config/allow_win32_input_mode.html" },
  ["use_ime"] = { doc = "Controls whether the Input Method Editor (IME) will be used to process keyboard input. The IME is useful for inputting kanji or other text that is not natively supported by the attached keyboard hardware. IME support is a platform dependent feature You can control whether the IME is enabled in your configuration file:", t = "bool", url = "https://wezterm.org/config/lua/config/use_ime.html" },
  ["ime_preedit_rendering"] = { doc = "Control IME preedit rendering. IME preedit is an area that is used to display the string being preedited in IME. WezTerm supports the following IME preedit rendering. \"Builtin\" - (Default) IME preedit is rendered by WezTerm itself \"Builtin\" rendering provides good look and feel for many IMEs, rendering the text using the same font as the terminal and works in concert with features like window:composition_status().", t = "enum", url = "https://wezterm.org/config/lua/config/ime_preedit_rendering.html", values = { "Builtin", "System" } },
  ["debug_key_events"] = { default = "false", doc = "When set to true, each key event will be logged by the GUI layer as an INFO level log message on the stderr stream from wezterm. You will typically need to launch wezterm directly from another terminal to see this logging. This can be helpful in figuring out how keys are being decoded on your system, or for discovering the system-dependent \"raw\" key code values. Produces logs like the following when typing ls: (artificially wrapped to make these docs more readable):", t = "bool", url = "https://wezterm.org/config/lua/config/debug_key_events.html" },
  ["ui_key_cap_rendering"] = { doc = "Controls how keyboard shortcuts are rendered in the Command Palette. Possible values are: \"UnixLong\" - Super, Meta, Ctrl, Shift. \"Emacs\" - Super, M, C, S. \"AppleSymbols\" - use macOS style symbols for Command, Option and so on. \"WindowsLong\" - Win, Alt, Ctrl, Shift. \"WindowsSymbols\" - like WindowsLong but using a logo for the Win key.", t = "enum", url = "https://wezterm.org/config/lua/config/ui_key_cap_rendering.html", values = { "UnixLong", "Emacs", "AppleSymbols", "WindowsLong", "WindowsSymbols" } },
  ["mouse_bindings"] = { doc = "Mouse bindings: a list of { event, mods, action } entries.", t = "complex" },
  ["disable_default_mouse_bindings"] = { default = "false", doc = "If set to true, the default mouse assignments will not be used, allowing you to tightly control those assignments.", t = "bool", url = "https://wezterm.org/config/lua/config/disable_default_mouse_bindings.html" },
  ["bypass_mouse_reporting_modifiers"] = { default = "\"SHIFT\"", doc = "If an application has enabled mouse reporting mode, mouse events are sent directly to the application, and do not get routed through the mouse assignment logic. Holding down the bypass_mouse_reporting_modifiers modifier key(s) will prevent the event from being passed to the application. The default value for bypass_mouse_reporting_modifiers is SHIFT, which means that holding down shift while clicking will not send the mouse event to eg: vim running in mouse mode and will instead treat the event as though SHIFT was not pressed and then match it against the mouse assignments.", empty = "NONE", t = "flags", url = "https://wezterm.org/config/lua/config/bypass_mouse_reporting_modifiers.html", values = { "SHIFT", "ALT", "CTRL", "SUPER", "LEADER" } },
  ["hide_mouse_cursor_when_typing"] = { doc = "If true, the mouse cursor will be hidden when typing, if your mouse cursor is hovering over the window. The default is true. Set to false to disable this behavior.", t = "bool", url = "https://wezterm.org/config/lua/config/hide_mouse_cursor_when_typing.html" },
  ["swallow_mouse_click_on_window_focus"] = { doc = "When set to true, clicking on a wezterm window will focus it. When set to false, clicking on a wezterm window will focus it and then pass through the click to the pane where the swallow_mouse_click_on_pane_focus option will further modify mouse event processing. The default is true on macOS but false on other systems.", t = "bool", url = "https://wezterm.org/config/lua/config/swallow_mouse_click_on_window_focus.html" },
  ["selection_word_boundary"] = { doc = "Configures the boundaries of a word, thus what is selected when doing a word selection with the mouse. (See mouse actions SelectTextAtMouseCursor & ExtendSelectionToMouseCursor with the mode argument set to Word) Defaults to \" \\t\\n{}[]()\\\"'\". For example, to always include spaces and newline when selecting a word, but stop on punctuations:", t = "string", url = "https://wezterm.org/config/lua/config/selection_word_boundary.html" },
  ["hyperlink_rules"] = { doc = "Defines rules to match text from the terminal output and generate clickable links. The value is a list of rule entries. Each entry has the following fields: regex - the regular expression to match (see supported Regex syntax) format - Controls which parts of the regex match will be used to form the link. Must have a prefix: signaling the protocol type (e.g., https:/mailto:), which can either come from the regex match or needs to be explicitly added. The format string can use placeholders like $0, $1, $2 etc. that will be replaced with that numbered capture group. So, $0 will take the entire region of text matched by the whole regex, while $1 matches out the first capture group. In the example below, mailto:$0 is used to prefix a protocol to the text to make it into an URL.", t = "complex", url = "https://wezterm.org/config/lua/config/hyperlink_rules.html" },
  ["quote_dropped_files"] = { doc = "Controls how file names are quoted (or not) when dragging and dropping. There are five possible values: \"None\" - no quoting is performed, the file name is passed through as-is. \"SpacesOnly\" - backslash-escape only spaces, leaving all other characters as-is. This is the default for non-Windows platforms. \"Posix\" - use POSIX style shell word escaping. \"Windows\" - use Windows style shell word escaping: double-quote filename with space characters in it, and leaving others as-is. This is the default on Windows. \"WindowsAlwaysQuoted\" - like \"Windows\", while always double-quote the filename. For example:", t = "enum", url = "https://wezterm.org/config/lua/config/quote_dropped_files.html", values = { "None", "SpacesOnly", "Posix", "Windows", "WindowsAlwaysQuoted" } },
  ["canonicalize_pasted_newlines"] = { doc = "Controls whether pasted text will have newlines normalized. If bracketed paste mode is enabled by the application, the effective value of this configuration option is \"None\". The following values are accepted:", nullable = true, t = "enum", url = "https://wezterm.org/config/lua/config/canonicalize_pasted_newlines.html", values = { "None", "LineFeed", "CarriageReturn", "CarriageReturnAndLineFeed" } },
  ["inactive_pane_hsb.hue"] = { doc = "Hue: field of inactive_pane_hsb. inactive_pane_hue, inactive_pane_saturation and inactive_pane_brightness allow for transforming the color of inactive panes.", t = "float" },
  ["inactive_pane_hsb.saturation"] = { doc = "Saturation: field of inactive_pane_hsb. inactive_pane_hue, inactive_pane_saturation and inactive_pane_brightness allow for transforming the color of inactive panes.", t = "float" },
  ["inactive_pane_hsb.brightness"] = { doc = "Brightness: field of inactive_pane_hsb. inactive_pane_hue, inactive_pane_saturation and inactive_pane_brightness allow for transforming the color of inactive panes.", t = "float" },
  ["unzoom_on_switch_pane"] = { default = "true", doc = "If set to false, the ActivatePaneDirection command will have no effect if the active pane is zoomed. If true, the active pane will be unzoomed first and then switched. See also: TogglePaneZoomState", t = "bool", url = "https://wezterm.org/config/lua/config/unzoom_on_switch_pane.html" },
  ["pane_focus_follows_mouse"] = { default = "false", doc = "When pane_focus_follows_mouse = true, moving the mouse pointer over an inactive pane will cause that pane to activate; this behavior is known as \"focus follows mouse\". When pane_focus_follows_mouse = false (the default), you need to click on an inactive pane to activate it.", t = "bool", url = "https://wezterm.org/config/lua/config/pane_focus_follows_mouse.html" },
  ["swallow_mouse_click_on_pane_focus"] = { default = "false", doc = "When set to true, clicking on a pane will focus it. When set to false (the default), clicking on a pane will focus it and then pass the click through to the application in the terminal.", t = "bool", url = "https://wezterm.org/config/lua/config/swallow_mouse_click_on_pane_focus.html" },
  ["quick_select_alphabet"] = { doc = "Specify the alphabet used to produce labels for the items matched in quick select mode. The default alphabet is \"asdfqwerzxcvjklmiuopghtybn\" which means that the first matching item from the bottom is labelled with an a, the second with s and so forth; these are easily accessible characters in a qwerty keyboard layout. The suggested alphabet in the above table uses the left 4 fingers on the home row, top row, bottom row, then the right 4 fingers on the home row, top row, bottom row, followed by the characters in the middle of the keyboard that may be harder to reach.", t = "string", url = "https://wezterm.org/config/lua/config/quick_select_alphabet.html" },
  ["quick_select_patterns"] = { doc = "Specify additional patterns to match when in quick select mode. This setting is a table listing out a set of regular expressions. If you want to use capture groups in your patterns, you must use non-capturing groups (?:) for them to work as you intend, as the overall list of quick_select_patterns is compiled into a larger alternation regex that itself uses capture groups. The regex syntax now supports backreferences and look around assertions. See Fancy Regex Syntax for the extended syntax, which builds atop the underlying Regex syntax. In prior versions, only the base Regex syntax was supported.", item = { t = "string" }, t = "list", url = "https://wezterm.org/config/lua/config/quick_select_patterns.html" },
  ["disable_default_quick_select_patterns"] = { default = "false", doc = "When set to true, the default set of quick select patterns are omitted, and your quick_select_patterns config specifies the total set of patterns used for quick select mode. Defaults to false.", t = "bool", url = "https://wezterm.org/config/lua/config/disable_default_quick_select_patterns.html" },
  ["quick_select_remove_styling"] = { default = "false", doc = "When set to true, all color and styling is removed from the pane prior to performing matching and highlighting any matching text in quick select mode. This can make it easier to focus on the matches, particularly when the pane already had a lot of styling and colors. Defaults to false", t = "bool", url = "https://wezterm.org/config/lua/config/quick_select_remove_styling.html" },
  ["launcher_alphabet"] = { doc = "Specify a string of unique characters. The characters in the string are used to calculate one or two key press shortcuts that can be used to quickly choose from the Launcher when in the default mode. Defaults to: \"1234567890abcdefghilmnopqrstuvwxyz\". (Without j/k so they can be used for movement up and down.)", t = "string", url = "https://wezterm.org/config/lua/config/launcher_alphabet.html" },
  ["launch_menu"] = { doc = "You can define your own entries for the Launcher Menu using this configuration setting. The snippet below adds two new entries to the menu; one that runs the top program to monitor process activity and a second one that explicitly launches the bash shell. Each entry in launch_menu is an instance of a SpawnCommand object.", t = "complex", url = "https://wezterm.org/config/lua/config/launch_menu.html" },
  ["command_palette_font"] = { doc = "Configures the font to use for command palette. The command_palette_font setting can specify a set of fallbacks and other options, and is described in more detail in the Fonts section. If not specified, the font is same as the font in window_frame.font You will typically use wezterm.font or wezterm.font_with_fallback to specify the font.", nullable = true, t = "font", url = "https://wezterm.org/config/lua/config/command_palette_font.html" },
  ["command_palette_font_size"] = { default = "14.0", doc = "Specifies the size of the font used with ActivateCommandPalette.", t = "float", url = "https://wezterm.org/config/lua/config/command_palette_font_size.html" },
  ["command_palette_line_height"] = { default = "1.0", doc = "Scales the computed line height used by ActivateCommandPalette. The default is 1.0, which uses the font-specified metrics. If the command palette feels too vertically cramped then you can set command_palette_line_height = 1.2 to increase the vertical spacing by 20%. Conversely, setting command_palette_line_height = 0.9 will decrease the vertical spacing by 10%. See also line_height, which only applies to terminal cells.", t = "float", url = "https://wezterm.org/config/lua/config/command_palette_line_height.html" },
  ["command_palette_rows"] = { default = "14", doc = "Specifies the number of rows displayed by the command palette. ActivateCommandPalette. If unset or nil, a default value based on the terminal display will be used.", nullable = true, t = "int", url = "https://wezterm.org/config/lua/config/command_palette_rows.html" },
  ["command_palette_fg_color"] = { default = "rgba(0.75, 0.75, 0.75, 1.0)", doc = "Specifies the text color used by ActivateCommandPalette.", t = "color", url = "https://wezterm.org/config/lua/config/command_palette_fg_color.html" },
  ["command_palette_bg_color"] = { default = "\"#333333\"", doc = "Specifies the background color used by ActivateCommandPalette.", t = "color", url = "https://wezterm.org/config/lua/config/command_palette_bg_color.html" },
  ["char_select_font"] = { doc = "Configures the font to use for character selection. The char_select_font setting can specify a set of fallbacks and other options, and is described in more detail in the Fonts section. If not specified, the font is same as the font in window_frame.font You will typically use wezterm.font or wezterm.font_with_fallback to specify the font.", nullable = true, t = "font", url = "https://wezterm.org/config/lua/config/char_select_font.html" },
  ["char_select_font_size"] = { default = "14.0", doc = "Specifies the size of the font used with CharSelect.", t = "float", url = "https://wezterm.org/config/lua/config/char_select_font_size.html" },
  ["char_select_fg_color"] = { default = "rgba(0.75, 0.75, 0.75, 1.0)", doc = "Specifies the text color used by CharSelect.", t = "color", url = "https://wezterm.org/config/lua/config/char_select_fg_color.html" },
  ["char_select_bg_color"] = { default = "\"#333333\"", doc = "Specifies the background color used by CharSelect.", t = "color", url = "https://wezterm.org/config/lua/config/char_select_bg_color.html" },
  ["pane_select_font"] = { doc = "Configures the font to use for pane selection mode. The pane_select_font setting can specify a set of fallbacks and other options, and is described in more detail in the Fonts section. If not specified, the font is same as the font in window_frame.font You will typically use wezterm.font or wezterm.font_with_fallback to specify the font.", nullable = true, t = "font", url = "https://wezterm.org/config/lua/config/pane_select_font.html" },
  ["pane_select_font_size"] = { doc = "Font size of the pane selection labels (PaneSelect).", t = "float" },
  ["pane_select_fg_color"] = { doc = "Text color of the pane selection labels (PaneSelect).", t = "color" },
  ["pane_select_bg_color"] = { doc = "Background color of the pane selection labels (PaneSelect).", t = "color" },
  ["palette_max_key_assigments_for_action"] = { doc = "How many key bindings the command palette shows next to an action.", t = "int" },
  ["default_prog"] = { applies = "new", doc = "If no prog is specified on the command line, use this instead of running the user's shell. For example, to have wezterm always run top by default, you'd use this: default_prog is implemented as an array where the 0th element is the command to run and the rest of the elements are passed as the positional arguments to that command.", item = { t = "string" }, nullable = true, t = "list", url = "https://wezterm.org/config/lua/config/default_prog.html" },
  ["default_cwd"] = { applies = "new", doc = "Sets the default current working directory used by the initial window. The value is a string specifying the absolute path that should be used for the home directory. Using strings like ~ or ~username that are typically expanded by the shell is not supported. You can use wezterm.home_dir to explicitly refer to your home directory. If wezterm start --cwd /some/path is used to specify the current working directory, that will take precedence.", nullable = true, t = "path", url = "https://wezterm.org/config/lua/config/default_cwd.html" },
  ["default_gui_startup_args"] = { applies = "restart", default = "{\"start\"}", doc = "When launching the GUI using either wezterm or wezterm-gui (with no subcommand explicitly specified), wezterm will use the value of default_gui_startup_args to pick a default mode for running the GUI. The default for this config is {\"start\"} which makes wezterm with no additional subcommand arguments equivalent to wezterm start. If you know that you always want to use wezterm's ssh client to login to a particular host, then you might consider using this configuration:", item = { t = "string" }, t = "list", url = "https://wezterm.org/config/lua/config/default_gui_startup_args.html" },
  ["set_environment_variables"] = { applies = "new", doc = "Specifies a map of environment variables that should be set when spawning new commands in the \"local\" domain. This configuration is consulted at the time that a program is launched. It is not possible to update the environment of a running program on any Operating System. This is not used when working with remote domains. See also: Launching Programs", item = { t = "string" }, t = "map", url = "https://wezterm.org/config/lua/config/set_environment_variables.html" },
  ["term"] = { applies = "new", default = "\"xterm-256color\"", doc = "What to set the TERM environment variable to. The default is xterm-256color, which should provide a good level of feature support without requiring the installation of additional terminfo data. If you want to get the most application support out of wezterm, then you may wish to install a copy of the wezterm TERM definition: You can then set term = \"wezterm\" in your .wezterm.lua config file.", t = "string", url = "https://wezterm.org/config/lua/config/term.html" },
  ["exit_behavior"] = { doc = "Controls the behavior when the shell program spawned by the terminal exits. There are three possible values: \"Close\" - close the corresponding pane as soon as the program exits. \"Hold\" - keep the pane open after the program exits. The pane must be manually closed via CloseCurrentPane, CloseCurrentTab or closing the window. \"CloseOnCleanExit\" - if the shell program exited with a successful status, behave like \"Close\", otherwise, behave like \"Hold\". This is the default setting. Note that most unix shells will exit with the status of the last command that it ran if you don't specify an exit status.", t = "enum", url = "https://wezterm.org/config/lua/config/exit_behavior.html", values = { "Close", "CloseOnCleanExit", "Hold" } },
  ["exit_behavior_messaging"] = { doc = "Controls how wezterm indicates the exit status of the spawned process in a pane when it terminates. If exit_behavior is set to keep the pane open after the process has completed, wezterm will display a message to let you know that it has finished. This option controls that message. It can have one of the following values:", t = "enum", url = "https://wezterm.org/config/lua/config/exit_behavior_messaging.html", values = { "Verbose", "Brief", "Terse", "None" } },
  ["clean_exit_codes"] = { doc = "Defines the set of exit codes that are considered to be a \"clean\" exit by exit_behavior when the program running in the terminal completes. Acceptable values are an array of integer exit codes that you wish to treat as successful. For example, if you often CTRL-C a program and then CTRL-D, bash will typically exit with status 130 to indicate that a program was terminated with SIGINT, but that bash itself wasn't. In that situation you may wish to set this config to treat 130 as OK:", item = { t = "int" }, t = "list", url = "https://wezterm.org/config/lua/config/clean_exit_codes.html" },
  ["skip_close_confirmation_for_processes_named"] = { doc = "This configuration specifies a list of process names that are considered to be \"stateless\" and that are safe to close without prompting when closing windows, panes or tabs. When closing a pane wezterm will try to determine the processes that were spawned by the program that was started in the pane. If all of those process names match one of the names in the skip_close_confirmation_for_processes_named list then it will not prompt for closing that particular pane. The default value for this setting is shown below:", item = { t = "string" }, t = "list", url = "https://wezterm.org/config/lua/config/skip_close_confirmation_for_processes_named.html" },
  ["detect_password_input"] = { default = "true", doc = "When set to true, on unix systems, for local panes, wezterm will query the termios associated with the PTY to see whether local echo is disabled and canonical input is enabled. If those conditions are met, then the text cursor will be changed to a lock to give a visual cue that what you type will not be echoed to the screen. This technique only works for local processes on unix systems, and will not work through other processes that themselves use PTYs. Most notably, this will not work with tmux or remote processes spawned via ssh.", t = "bool", url = "https://wezterm.org/config/lua/config/detect_password_input.html" },
  ["default_domain"] = { applies = "new", default = "\"local\"", doc = "This option only applies to the GUI. For the equivalent option in the standalone mux server, see default_mux_server_domain When starting the GUI (not using the serial or connect subcommands), by default wezterm will set the built-in \"local\" domain as the default multiplexing domain. The \"local\" domain represents processes that are spawned directly on the local system.", nullable = true, t = "string", url = "https://wezterm.org/config/lua/config/default_domain.html" },
  ["default_workspace"] = { applies = "new", default = "\"default\"", doc = "Specifies the name of the default workspace. The default is \"default\".", nullable = true, t = "string", url = "https://wezterm.org/config/lua/config/default_workspace.html" },
  ["unicode_version"] = { default = "9", doc = "Specifies the version of unicode that will be used when interpreting the width/presentation of text. This option exists because Unicode is an evolving specification that introduces new features and that occasionally adjusts how existing features should be handled. For example, there were a number of unicode code points that had their width changed between Unicode version 8 and version 9. This wouldn't be an issue if all software was simultaneously aware of the change, but the reality is that there is a lot of older software out there, and that even if your local system is fully up to date, you might connect to a remote system vis SSH that is running applications that use a different version of unicode than your local system.", t = "int", url = "https://wezterm.org/config/lua/config/unicode_version.html" },
  ["treat_east_asian_ambiguous_width_as_wide"] = { default = "false", doc = "Unicode defines a number of codepoints as having Ambiguous Width. These are characters whose width resolves differently according to context that is typically absent from the monospaced world of the terminal. WezTerm will by default treat ambiguous width as occupying a single cell. When treat_east_asian_ambiguous_width_as_wide = true WezTerm will treat them as being two cells wide.", t = "bool", url = "https://wezterm.org/config/lua/config/treat_east_asian_ambiguous_width_as_wide.html" },
  ["cell_widths"] = { default = "{}", doc = "The character width recommended by the Unicode standard is occasionally inconsistent and may not align with linguistic tradition. - circled numbers width: ⓪①..⑳㉑ - lowercase Roman numerals width: ⅹⅺⅻ - Nerd Font (Private Use Area) character width - ambiguous character width for CJK text - square emojis defined as EAW=Neutral The cell_widths configuration parameter allows users to override the default character width. This setting takes priority over the treat_east_asian_ambiguous_width_as_wide setting.", nullable = true, t = "complex", url = "https://wezterm.org/config/lua/config/cell_widths.html" },
  ["normalize_output_to_unicode_nfc"] = { default = "false", doc = "When set to true, contiguous runs codepoints output to the terminal are normalized to Unicode Normalization Form C (NFC). This can improve the display of text and in the terminal when portions of the output are in other normalization forms, particularly with Korean text where a given glyph can be comprised of several codepoints. However, depending on the application running inside the terminal, enabling this option may introduce discrepancies in the understanding of text positioning: while it may fix some display glitches for some applications, it may trade them for other glitches.", t = "bool", url = "https://wezterm.org/config/lua/config/normalize_output_to_unicode_nfc.html" },
  ["bidi_enabled"] = { doc = "Enable bidirectional text (right-to-left scripts such as Arabic and Hebrew).", t = "bool" },
  ["bidi_direction"] = { doc = "Paragraph direction used for bidirectional text.", t = "enum", values = { "LeftToRight", "RightToLeft", "AutoLeftToRight", "AutoRightToLeft" } },
  ["enable_kitty_graphics"] = { doc = "Allow programs to show images with the kitty graphics protocol.", t = "bool" },
  ["enable_title_reporting"] = { doc = "Whether the terminal should respond to requests to read the title string. Disabled by default for security concerns with shells that might otherwise attempt to execute the response.", t = "bool" },
  ["enq_answerback"] = { doc = "Text sent back to a program that sends the ENQ control character.", t = "string" },
  ["enable_checksum_rectangular_area"] = { doc = "Whether the terminal should respond to DECRQCRA checksum requests. Disabled by default as it allows programs to read screen contents.", t = "bool" },
  ["log_unknown_escape_sequences"] = { default = "false", doc = "When set to true, wezterm will log warnings when it receives escape sequences which it does not understand. Those warnings are harmless and are useful primarily by the maintainer to discover new and interesting escape sequences. In previous versions, there was no option to control this, and wezterm would always log warnings for unknown escape sequences.", t = "bool", url = "https://wezterm.org/config/lua/config/log_unknown_escape_sequences.html" },
  ["allow_download_protocols"] = { doc = "Allow programs to send files to wezterm for download through escape sequences.", t = "bool" },
  ["notification_handling"] = { default = "\"AlwaysShow\"", doc = "This option controls how wezterm behaves when a toast notification escape sequence is received. The following escape sequences will generate a toast notification: This configuration option can have one of the following values, which have the following effects:", t = "enum", url = "https://wezterm.org/config/lua/config/notification_handling.html", values = { "AlwaysShow", "NeverShow", "SuppressFromFocusedPane", "SuppressFromFocusedTab", "SuppressFromFocusedWindow" } },
  ["audible_bell"] = { doc = "When the BEL ascii sequence is sent to a pane, the bell is \"rung\" in that pane. You may choose to configure the audible_bell option to change the sound that wezterm makes when the bell rings. The follow are possible values:", t = "enum", url = "https://wezterm.org/config/lua/config/audible_bell.html", values = { "SystemBeep", "Disabled" } },
  ["visual_bell.fade_in_duration_ms"] = { doc = "Fade in duration ms: field of visual_bell. When the BEL ascii sequence is sent to a pane, the bell is \"rung\" in that pane.", t = "int", url = "https://wezterm.org/config/lua/config/visual_bell.html" },
  ["visual_bell.fade_in_function"] = { doc = "Fade in function: field of visual_bell. When the BEL ascii sequence is sent to a pane, the bell is \"rung\" in that pane.", t = "enum", url = "https://wezterm.org/config/lua/config/visual_bell.html", values = { "Linear", "Ease", "EaseIn", "EaseInOut", "EaseOut", "Constant" } },
  ["visual_bell.fade_out_duration_ms"] = { doc = "Fade out duration ms: field of visual_bell. When the BEL ascii sequence is sent to a pane, the bell is \"rung\" in that pane.", t = "int", url = "https://wezterm.org/config/lua/config/visual_bell.html" },
  ["visual_bell.fade_out_function"] = { doc = "Fade out function: field of visual_bell. When the BEL ascii sequence is sent to a pane, the bell is \"rung\" in that pane.", t = "enum", url = "https://wezterm.org/config/lua/config/visual_bell.html", values = { "Linear", "Ease", "EaseIn", "EaseInOut", "EaseOut", "Constant" } },
  ["visual_bell.target"] = { doc = "Target: field of visual_bell. When the BEL ascii sequence is sent to a pane, the bell is \"rung\" in that pane.", t = "enum", url = "https://wezterm.org/config/lua/config/visual_bell.html", values = { "BackgroundColor", "CursorColor" } },
  ["unix_domains"] = { applies = "restart", doc = "Defines a list of multiplexer domains for both the multiplexer server and multiplexer client. Read more about multiplexing", t = "complex", url = "https://wezterm.org/config/lua/config/unix_domains.html" },
  ["ssh_domains"] = { applies = "restart", doc = "Configures SSH multiplexing domains. Read more about SSH Domains. This option accepts a list of SshDomain objects. If you don't set ssh_domains in your config, wezterm will default to configuring it as if you had:", nullable = true, t = "complex", url = "https://wezterm.org/config/lua/config/ssh_domains.html" },
  ["ssh_backend"] = { applies = "restart", default = "\"LibSsh\"", doc = "Sets which ssh backend should be used by default for the integrated ssh client. Possible values are: \"Ssh2\" - use libssh2 \"LibSsh\" - use libssh", t = "enum", url = "https://wezterm.org/config/lua/config/ssh_backend.html", values = { "Ssh2", "LibSsh" } },
  ["tls_servers"] = { applies = "restart", doc = "Configures TLS multiplexing domains. Read more about TLS Domains. This option accepts a list of TlsDomainServer objects.", t = "complex", url = "https://wezterm.org/config/lua/config/tls_servers.html" },
  ["tls_clients"] = { applies = "restart", doc = "Configures TLS multiplexing domains. Read more about TLS Domains. This option accepts a list of TlsDomainClient objects.", t = "complex", url = "https://wezterm.org/config/lua/config/tls_clients.html" },
  ["wsl_domains"] = { applies = "restart", doc = "Configures WSL domains. This option accepts a list of WslDomain objects. The default is a list derived from parsing the output of wsl -l -v. See wezterm.default_wsl_domains() for more about that list, and on how to override it.", nullable = true, t = "complex", url = "https://wezterm.org/config/lua/config/wsl_domains.html" },
  ["exec_domains"] = { applies = "restart", doc = "Exec domains: run each new pane through a Lua callback that can rewrite the command.", t = "complex" },
  ["serial_ports"] = { applies = "restart", default = "{}", doc = "Define a list of serial port(s) that you use regularly. Each entry defines a SerialDomain with the following fields: name - the name to use for the serial domain. Must be unique across all multiplexer domains in your configuration. port - the name of the serial device. On Windows systems this can be a name like COM0. On Posix systems this will be a device path something like /dev/ttyUSB0. If omitted, the name field be interpreted as the port name. baud - the communication speed to assign to the port. If omitted, the default baud rate will be 9600. This configuration defines a single port:", t = "complex", url = "https://wezterm.org/config/lua/config/serial_ports.html" },
  ["default_mux_server_domain"] = { applies = "restart", default = "\"local\"", doc = "This option only applies to the standalone mux server. For the equivalent option in the GUI, see default_domain When starting the mux server, by default wezterm will set the built-in \"local\" domain as the default multiplexing domain. The \"local\" domain represents processes that are spawned directly on the local system.", nullable = true, t = "string", url = "https://wezterm.org/config/lua/config/default_mux_server_domain.html" },
  ["mux_enable_ssh_agent"] = { applies = "restart", default = "true", doc = "When set to true (the default), wezterm will configure the SSH_AUTH_SOCK environment variable for panes spawned in the local domain. The auth sock will point to a symbolic link that will in turn be pointed to the authentication socket associated with the most recently active multiplexer client. You can review the authentication socket that will be used for various clients by running wezterm cli list-clients and inspecting the SSH_AUTH_SOCK column.", t = "bool", url = "https://wezterm.org/config/lua/config/mux_enable_ssh_agent.html" },
  ["default_ssh_auth_sock"] = { doc = "Setting this value will cause wezterm to replace the value of the SSH_AUTH_SOCK environment when it first starts up, and to use this value for the auth socket registered with the multiplexer server (visible via wezterm cli list-clients). You won't normally need to set this, but if you are running with an alternative identity agent and want to replace the default on your system, this gives you that ability. For example, @wez currently uses the 1Password SSH Auth Agent, but when running on Gnome the system default is Gnome's keyring agent.", nullable = true, t = "string", url = "https://wezterm.org/config/lua/config/default_ssh_auth_sock.html" },
  ["mux_env_remove"] = { doc = "Specifies a list of environment variables that should be removed from the environment in the multiplexer server. The intent is to clean up environment variables that might give the wrong impression of their operating environment to the various terminal sessions spawned by the multiplexer server. The default value for this is:", item = { t = "string" }, t = "list", url = "https://wezterm.org/config/lua/config/mux_env_remove.html" },
  ["mux_output_parser_buffer_size"] = { doc = "The buffer size used by parse_buffered_data in the mux module. This should not be too large, otherwise the processing cost of applying a batch of actions to the terminal will be too high and the user experience will be laggy and less responsive.", t = "int" },
  ["mux_output_parser_coalesce_delay_ms"] = { doc = "How many ms to delay after reading a chunk of output in order to try to coalesce fragmented writes into a single bigger chunk of output and reduce the chances observing \"screen tearing\" with un-synchronized output", t = "int" },
  ["ratelimit_mux_line_prefetches_per_second"] = { doc = "Constrains the rate at which the multiplexer client will speculatively fetch line data. This helps to avoid saturating the link between the client and server if the server is dumping a large amount of output to the client.", t = "int" },
  ["daemon_options"] = { applies = "restart", doc = "Allows configuring the multiplexer (mux) server and how it places itself into the background to run as a daemon process. You should not normally need to configure this setting; the defaults should be sufficient in most cases. There are three fields supported: pid_file - specify the location of the pid and lock file. The default location is $XDG_RUNTIME_DIR/wezterm/pid on X11/Wayland systems, or $HOME/.local/share/wezterm/pid stdout - specifies where a log of the stdout stream from the daemon will be placed. The default is $XDG_RUNTIME_DIR/wezterm/stdout on X11/Wayland systems, or $HOME/.local/share/wezterm/stdout. stderr - specifies where a log of the stderr stream from the daemon will be placed. The default is $XDG_RUNTIME_DIR/wezterm/stderr on X11/Wayland systems, or $HOME/.local/share/wezterm/stderr.", t = "complex", url = "https://wezterm.org/config/lua/config/daemon_options.html" },
  ["front_end"] = { applies = "restart", default = "\"OpenGL\"", doc = "Specifies which render front-end to use. This option used to have more scope in earlier versions of wezterm, but today it allows three possible values: OpenGL - use GPU accelerated rasterization Software - use CPU-based rasterization. WebGpu - use GPU accelerated rasterization The default is \"WebGpu\". In earlier versions it was \"OpenGL\"", note = "CRT effects are drawn by the OpenGL front end only.", t = "enum", url = "https://wezterm.org/config/lua/config/front_end.html", values = { "OpenGL", "WebGpu", "Software" } },
  ["webgpu_power_preference"] = { applies = "restart", default = "\"LowPower\"", doc = "Specifies the power preference when selecting a webgpu GPU instance. This option is only applicable when you have configured front_end = \"WebGpu\". The possible values are: \"LowPower\" - use an integrated GPU \"HighPerformance\" - use a discrete GPU", t = "enum", url = "https://wezterm.org/config/lua/config/webgpu_power_preference.html", values = { "LowPower", "HighPerformance" } },
  ["webgpu_force_fallback_adapter"] = { applies = "restart", default = "false", doc = "If set to true, forces the use of a fallback software (CPU based) rendering backend. The performance will not be as good as using a GPU. This option is only applicable when you have configured front_end = \"WebGpu\". You can have more fine grained control over which GPU is selected using webgpu_preferred_adapter.", t = "bool", url = "https://wezterm.org/config/lua/config/webgpu_force_fallback_adapter.html" },
  ["webgpu_preferred_adapter"] = { applies = "restart", doc = "Specifies which WebGpu adapter should be used. This option is only applicable when you have configured front_end = \"WebGpu\". You can use the wezterm.gui.enumerate_gpus() function to return a list of GPUs.", nullable = true, t = "gpu", url = "https://wezterm.org/config/lua/config/webgpu_preferred_adapter.html" },
  ["prefer_egl"] = { applies = "restart", default = "true", doc = "Depending on the OS and windowing environment, there are a number of different ways to access the GPU. This option controls whether wezterm should attempt to use EGL to configure the GPU. The default is true.", t = "bool", url = "https://wezterm.org/config/lua/config/prefer_egl.html" },
  ["max_fps"] = { default = "60", doc = "Limits the maximum number of frames per second that wezterm will attempt to draw. Defaults to 60.", t = "int", url = "https://wezterm.org/config/lua/config/max_fps.html" },
  ["shape_cache_size"] = { doc = "Size of the text shaping cache (entries).", t = "int" },
  ["line_state_cache_size"] = { doc = "Size of the line state cache (entries).", t = "int" },
  ["line_quad_cache_size"] = { doc = "Size of the line geometry cache (entries).", t = "int" },
  ["line_to_ele_shape_cache_size"] = { doc = "Size of the line to element shape cache (entries).", t = "int" },
  ["glyph_cache_image_cache_size"] = { doc = "Size of the glyph image cache (entries).", t = "int" },
  ["periodic_stat_logging"] = { doc = "If non-zero, specifies the period (in seconds) at which various statistics are logged. Note that there is a minimum period of 10 seconds.", t = "int" },
  ["automatically_reload_config"] = { doc = "When true (the default), watch the config file and reload it automatically when it is detected as changing. When false, you will need to manually trigger a config reload with a key bound to the action ReloadConfiguration. For example, to disable auto config reload:", t = "bool", url = "https://wezterm.org/config/lua/config/automatically_reload_config.html" },
  ["check_for_updates"] = { doc = "Wezterm checks regularly if there is a new stable version available on github, and shows a simple UI to let you know about the update (See show_update_window to control this UI). By default it is checked once every 24 hours. NOTE that it doesn't automatically download the release. No data are collected for the wezterm project as part of this.", t = "bool", url = "https://wezterm.org/config/lua/config/check_for_updates.html" },
  ["check_for_updates_interval_seconds"] = { doc = "How often to check for a new wezterm release, in seconds.", t = "int" },
  ["show_update_window"] = { doc = "When Wezterm checks for an update and detects a new version, this option controls whether a window is shown with information about the new available version and links to download/install it. See check_for_updates for more information on the automatic update checks. This option no longer has any effect and will be removed in a future release.", t = "bool", url = "https://wezterm.org/config/lua/config/show_update_window.html" },
  ["macos_window_background_blur"] = { default = "0", doc = "When combined with window_background_opacity, configures the blur radius amount used by macOS when compositing the window on the screen. This can be used to produce a translucent window effect rather than a crystal clear transparent window effect. The screenshot below was achieved using this configuration:", t = "int", url = "https://wezterm.org/config/lua/config/macos_window_background_blur.html" },
  ["kde_window_background_blur"] = { default = "false", doc = "Deprecated; this option was added & deprecated in the same version. Use wayland_window_background_blur instead When combined with window_background_opacity, enables background blur using the KDE Wayland blur protocol. This can be used to produce a translucent window effect rather than a crystal clear transparent window effect.", t = "bool", url = "https://wezterm.org/config/lua/config/kde_window_background_blur.html" },
  ["wayland_window_background_blur"] = { doc = "When combined with window_background_opacity, enables background blur using the Wayland background effect protocol. This can be used to produce a translucent window effect rather than a crystal clear transparent window effect. This effect can be achieved by adding the following to the configuration:", t = "bool", url = "https://wezterm.org/config/lua/config/wayland_window_background_blur.html" },
  ["native_macos_fullscreen_mode"] = { default = "false", doc = "Specifies whether the ToggleFullScreen key assignment uses the native macOS full-screen application support or not. The default is false which will simply (and very quickly!) toggle between a window that covers the full screen, with no decorations and a regularly sized window. When true, transitioning to full screen will use the macOS native full screen mode, which in more recent versions of macOS, will allocate a separate Space for the wezterm application and then slowly animate the wezterm window moving into to that full screen Space on the monitor.", t = "bool", url = "https://wezterm.org/config/lua/config/native_macos_fullscreen_mode.html" },
  ["macos_fullscreen_extend_behind_notch"] = { default = "false", doc = "When true and in full screen mode, the window will extend behind the notch on macOS. The default value for macos_fullscreen_extend_behind_notch is false. Must be used with native_macos_fullscreen_mode set to false.", t = "bool", url = "https://wezterm.org/config/lua/config/macos_fullscreen_extend_behind_notch.html" },
  ["macos_forward_to_ime_modifier_mask"] = { default = "\"SHIFT\"", doc = "On macOS systems, this option controls whether modified key presses are routed via the IME when use_ime = true. When processing a key event, if any modifiers are held, if the modifiers intersect with the value of macos_forward_to_ime_modifier_mask, then the key event is routed to the IME, which may choose to swallow the key event as part of its own state management. The behavior of wezterm has varied in the past:", empty = "NONE", t = "flags", url = "https://wezterm.org/config/lua/config/macos_forward_to_ime_modifier_mask.html", values = { "SHIFT", "ALT", "CTRL", "SUPER", "LEADER" } },
  ["enable_wayland"] = { applies = "restart", doc = "If false, do not try to use a Wayland protocol connection when starting the gui frontend, and instead use X11. This option is only considered on X11/Wayland systems and has no effect on macOS or Windows. The default is true. In versions prior to 20220624-141144-bd1b7c5d it was disabled by default.", t = "bool", url = "https://wezterm.org/config/lua/config/enable_wayland.html" },
  ["enable_zwlr_output_manager"] = { doc = "Wayland: use the zwlr output manager protocol to get screen names and scaling.", t = "bool" },
  ["xim_im_name"] = { doc = "Explicitly set the name of the IME server to which wezterm will connect via the XIM protocol when using X11 and use_ime is true. By default, this option is not set which means that wezterm will consider the value of the XMODIFIERS environment variable. If for some reason the environment isn't set up correctly, or you want to quickly evaluate a different input method server, then you could update your config to specify it explicitly:", nullable = true, t = "string", url = "https://wezterm.org/config/lua/config/xim_im_name.html" },
  ["xcursor_theme"] = { doc = "X11/Wayland: mouse cursor theme.", nullable = true, t = "string" },
  ["xcursor_size"] = { doc = "X11/Wayland: mouse cursor size.", nullable = true, t = "int" },
  ["tiling_desktop_environments"] = { default = "{}", doc = "Contains a list of Window Environments that are known to be tiling window managers. A tiling window manager is one that automatically resizes windows according to some layout policy, rather than respecting the window size set by an application. The default value for this option is: The following additional entries are now part of the default value of tiling_desktop_environments:", item = { t = "string" }, t = "list", url = "https://wezterm.org/config/lua/config/tiling_desktop_environments.html" },
  ["ulimit_nofile"] = { applies = "restart", default = "2048", doc = "On Unix systems, specifies the minimum desirable value for the RLIMIT_NOFILE soft limit. That system parameter controls the maximum number of file descriptors that a given process is permitted to open. On startup, wezterm will inspect the soft and hard limits, and if the soft limit is below the value of the ulimit_nofile option, wezterm will attempt to raise it to min(ulimit_nofile, hard_limit).", t = "int", url = "https://wezterm.org/config/lua/config/ulimit_nofile.html" },
  ["ulimit_nproc"] = { applies = "restart", default = "2048", doc = "On Unix systems, specifies the minimum desirable value for the RLIMIT_NPROC soft limit. That system parameter controls the maximum number of simultaneous processes that a given user is permitted to spawn. On startup, wezterm will inspect the soft and hard limits, and if the soft limit is below the value of the ulimit_nproc option, wezterm will attempt to raise it to min(ulimit_nproc, hard_limit).", t = "int", url = "https://wezterm.org/config/lua/config/ulimit_nproc.html" },
}
return M
